      'Present Perfect (has/have + V3) shifts to Past Perfect (had + V3).',
      'Simple Past (V2) shifts to Past Perfect (had + V3)!',
      'Past Continuous (was/were + V-ing) shifts to Past Perfect Continuous (had been + V-ing)!',
      'Modal shifts: will -> would, shall -> should/would, can -> could, may -> might. (Must often stays must or becomes had to).'
