      '४. साधा भूतकाळ ➔ पूर्ण भूतकाळ (V2 ➔ had + V3). हा अत्यंत महत्त्वाचा बदल आहे!',
      '५. चालू भूतकाळ ➔ चालू पूर्ण भूतकाळ (was/were ➔ had been).',
