      'Words starting with consonant letter but silent \'h\' or vowel sound take "An": an hour (उच्चार \'आवर\'), an honest man (\'ऑनेस्ट\'), an heir (\'एअर\' - वारस), an honourable person.',
      'Abbreviations / Acronyms starting with vowel sound take "An": an MLA (उच्चार \'एम.एल.ए.\' - \'ए\'), an MP, an FIR, an SP, an SDO, an MBA, an NCC cadet, an X-ray.'
