      'Beside: Means "by the side of" or "next to" (e.g., "Come and sit beside me").',
      'Besides: Means "in addition to" or "apart from" (e.g., "Besides Marathi, he can speak French").',
      'Between: Used for TWO persons or things (e.g., "Divide the property between the two brothers"). Note: Can be used for more than two if there is mutual reciprocal agreement (e.g. "A treaty between the four nations").',
      'Among: Used for MORE THAN TWO persons or things (e.g., "Distribute sweets among the school children").'
