      'TRAP 1 - "I am": The negative tag for "I am" is ALWAYS "aren\'t I?" (There is NO word "amn\'t" in English!). BUT positive tag is "am I?": "I am not late, am I?"',
      'TRAP 2 - Inherent Negative Words: Words like seldom, hardly, scarcely, barely, rarely, neither, none, nobody, few, little carry negative meaning. Hence, their tag MUST BE POSITIVE! (e.g. "He seldom smiles, DOES HE?").',
      'TRAP 3 - "Let\'s": Sentences starting with "Let\'s" or "Let us" take the tag "SHALL WE?" (e.g. "Let\'s play cricket, shall we?").',
      'TRAP 4 - Imperative with command takes "WILL YOU?" or "WON\'T YOU?" (e.g. "Open the gate, will you?").',
      'TRAP 5 - Indefinite Pronouns: When the subject is "Everyone", "Everybody", "Someone", "Nobody", the tag pronoun is "THEY" with a plural verb! (e.g. "Everyone was present, WEREN\'T THEY?").'
