      '२. "I am" चा नकारार्थी टॅग \'aren\'t I?\' होतो (\'amn\'t I\' हा शब्द अस्तित्वात नाही!).',
      '३. अंतर्भूत नकारार्थी शब्द (Hardly, Scarcely, Seldom, Rarely, Barely, Few, Little) वाक्यात आल्यास वाक्य नकारार्थी मानले जाते, म्हणून टॅग होकारार्थी येतो (उदा. He seldom comes, does he?).',
      '४. "Let\'s" ने सुरू होणाऱ्या वाक्याचा टॅग नेहमी \'shall we?\' होतो.',
      '५. Everyone, Everybody, Someone, Nobody आल्यास टॅगमध्ये \'they\' हे सर्वनाम येते आणि क्रियापद अनेकवचनी होते (उदा. Everyone was happy, weren\'t they?).'
