    examTipMr: 'MPSC सोपी क्लृप्ती:\n• चांगली गोष्ट = २-३-१ (दुसऱ्याला मान आधी, स्वतः शेवटी).\n• वाईट गोष्ट किंवा चूक = १-२-३ (स्वतःची चूक आधी मान्य करा).\n• तिन्ही अनेकवचनी (We, you, they) = १-२-३.',
