        explanationMr: 'बरोबर! "the greatest" हे Superlative रूप असल्याने व्यक्तीचा उल्लेख असूनही "who" ऐवजी "that" चा वापर व्याकरणाच्या नियमानुसार अनिवार्य आहे.'
