    examTipMr: 'MPSC २ सेकंदांची क्लृप्ती: वाक्यात किती व्यक्ती आहेत ते मोजा!\n• जर दोन (Two / Both) असतील ➔ EACH OTHER\n• जर दोनापेक्षा जास्त (Three, All, Team, Students) असतील ➔ ONE ANOTHER',
